<script setup lang="ts">
import LeadCard from './LeadCard.vue'
import QuickActions from './QuickActions.vue'
import { heat, terminalStage } from '~/utils/prospecting'
import LeadEditor from './LeadEditor.vue'
import LeadDetail from './LeadDetail.vue'
import Results from './Results.vue'
import Playbook from './Playbook.vue'
import MigrationBanner from './MigrationBanner.vue'
import type { Prospect } from '~/types/prospecting'
import { prospectStages, prospectStageLabels } from '~/constants/prospecting'
import { supabase } from '~/composables/useSupabase'
const store = useProspecting()
const { data, ready, blocked, error, notice, query, city, segment, priority, stage, view, today, active, due, filtered, stats, pendingImport, sort, returnFilter, returnCounts } = store
const editor = ref<InstanceType<typeof LeadEditor> | null>(null)
const detail = ref<InstanceType<typeof LeadDetail> | null>(null)
const selectedId = ref('')
const selected = computed(() => data.value.leads.find(lead => lead.id === selectedId.value) || null)
const arrangement = ref('Lista')
const target = ref(30)
const budget = ref(0)
watch(() => data.value.settings, value => { target.value = value.target; budget.value = value.budget }, { immediate: true })
const cities = computed(() => [...new Set(data.value.leads.map(lead => lead.city))].sort())
const segments = computed(() => [...new Set(data.value.leads.map(lead => lead.segment))].sort())
async function open(lead: Prospect, focusInteraction = false) { selectedId.value = lead.id; await nextTick(); detail.value?.open(lead, focusInteraction) }
async function importFile(event: Event) { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (file) await store.prepareImport(file); input.value = '' }
function changeView(value: string) { view.value = value; store.clearFilters(); if (value === 'Retornos') sort.value = 'followup' }
async function logout() { await supabase.auth.signOut(); navigateTo('/prospeccao/login') }
const scheduleDialog = ref<HTMLDialogElement | null>(null)
const scheduleLead = ref<Prospect | null>(null)
const scheduleDate = ref('')
const scheduleAction = ref('')
const scheduleSaving = ref(false)
const scheduleError = ref('')
async function schedule(lead: Prospect) {
  scheduleLead.value = JSON.parse(JSON.stringify(lead))
  scheduleDate.value = lead.followUp && lead.followUp >= today.value ? lead.followUp : today.value
  scheduleAction.value = lead.nextAction
  scheduleError.value = ''
  await nextTick()
  scheduleDialog.value?.showModal()
}
async function saveSchedule() {
  if (!scheduleLead.value || scheduleSaving.value) return
  const current = data.value.leads.find(item => item.id === scheduleLead.value!.id)
  if (!current || current.updatedAt !== scheduleLead.value.updatedAt || terminalStage(current.stage)) {
    scheduleError.value = 'A empresa foi alterada. Feche e reabra o agendamento.'; return
  }
  scheduleSaving.value = true
  try {
    if (await store.save({ ...current, followUp: scheduleDate.value, nextAction: scheduleAction.value })) scheduleDialog.value?.close()
    else scheduleError.value = error.value
  } finally { scheduleSaving.value = false }
}
const settingsSaving = ref(false)
async function saveSettings() {
  if (settingsSaving.value) return
  settingsSaving.value = true
  try { await store.settings({ target: target.value, budget: budget.value }) }
  finally { settingsSaving.value = false }
}
</script>
<template>
  <div class="min-h-screen bg-[#f3f6fb] font-body text-[#17253e] [&_input]:max-w-full [&_input]:text-base [&_select]:max-w-full [&_select]:text-base [&_textarea]:text-base [&_p]:break-words">
    <div class="lg:fixed lg:inset-y-0 lg:left-0 lg:w-60"><aside class="flex h-full flex-col bg-[#14243e] px-5 py-6 text-white"><NuxtLink to="/" class="text-3xl font-bold tracking-tight">avyro<span class="text-blue-300">.</span></NuxtLink><p class="mt-2 text-xs uppercase tracking-[0.2em] text-slate-400">Prospecção ativa</p><nav aria-label="Painel de prospecção" class="mt-7 flex flex-wrap gap-2 lg:flex-col"><button v-for="(item, i) in ['Contatos', 'Retornos', 'Resultados', 'Guia de prospecção', 'Arquivados', 'Configurações']" :key="item" class="flex min-h-11 items-center justify-between gap-4 rounded-lg px-4 py-3 text-left text-sm" :class="view === item ? 'bg-[#2c4162] text-white' : 'text-slate-300 hover:bg-white/10'" :aria-current="view === item ? 'page' : undefined" @click="changeView(item)"><span><span class="mr-3 text-slate-400">0{{ i + 1 }}</span>{{ item === 'Contatos' ? 'Empresas cadastradas' : item }}</span><span v-if="item === 'Retornos' && due.length" class="rounded-full bg-amber-300 px-2 text-xs text-slate-900">{{ due.length }}</span></button></nav><div class="mt-7 hidden rounded-xl border border-white/15 p-4 text-xs leading-6 text-slate-300 lg:block">Uma cidade por vez.<br>Uma abordagem com contexto.<br>Um próximo passo registrado.</div><button class="mt-4 hidden min-h-10 rounded-lg border border-white/10 px-4 text-xs text-slate-400 hover:text-white lg:block" @click="logout">Sair do painel</button></aside></div>
    <main class="px-4 py-7 sm:px-7 lg:ml-60 lg:px-10"><header class="mx-auto flex max-w-[1440px] flex-col justify-between gap-5 sm:flex-row sm:items-center"><div><p class="text-xs text-slate-500">Seu espaço de trabalho / {{ today.split('-').reverse().join('/') }}</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">{{ view === 'Contatos' ? 'Empresas cadastradas' : view }}</h1></div><button :disabled="!ready || blocked" class="min-h-12 rounded-xl bg-[#2458df] px-6 py-3 text-sm font-semibold text-white shadow-sm disabled:opacity-50" @click="editor?.open()">+ Nova empresa</button></header>
      <div class="mx-auto max-w-[1440px]"><MigrationBanner /><p v-if="ready && !blocked && !error" class="mt-5 text-xs leading-6 text-slate-500">Dados carregados do banco · Dados protegidos e acessíveis no seu próximo login. Exporte backups para cópias locais.</p><div v-if="error" role="alert" class="mt-4 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-800">{{ error }}</div><div v-if="notice" role="status" class="mt-4 flex items-center justify-between gap-4 rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-2 text-sm text-emerald-800"><span>{{ notice }}</span><button aria-label="Dispensar aviso" class="h-11 w-11 shrink-0" @click="notice = ''">✕</button></div>
        <p v-if="!ready" role="status" class="py-20 text-center text-slate-500">Abrindo seus contatos…</p>
        <p v-else-if="blocked" class="py-12 text-center text-slate-600">Os dados não foram carregados. Recarregue o painel para tentar novamente.</p><template v-else>
          <div class="my-7 grid grid-cols-2 gap-3 xl:grid-cols-5"><div v-for="item in [{ label: 'Empresas cadastradas', value: stats.registered, sub: 'Cadastros ativos, incluindo não contatadas' }, { label: 'Empresas contatadas', value: `${stats.contacted} / ${data.settings.target}`, sub: 'Sua meta de prospecção' }, { label: 'Respostas recebidas', value: stats.responses, sub: stats.contacted ? `${Math.round(stats.responses / stats.contacted * 100)}% das contatadas` : 'Registre o primeiro contato' }, { label: 'Demonstraram interesse', value: stats.interested, sub: 'Empresas únicas no histórico' }, { label: 'Retornos até hoje', value: due.length, sub: 'Pendentes e sem encerramento' }]" :key="item.label" class="rounded-xl border border-slate-200 bg-white p-4 sm:p-5"><p class="text-xs text-slate-500">{{ item.label }}</p><p class="mt-3 text-2xl font-semibold sm:text-3xl">{{ item.value }}</p><p class="mt-3 text-[11px] leading-5 text-slate-500">{{ item.sub }}</p></div></div>
          <Playbook v-if="view === 'Guia de prospecção'" />
          <Results v-else-if="view === 'Resultados'" :leads="data.leads" :settings="data.settings" />
          <div v-else-if="view === 'Configurações'" class="grid gap-6 xl:grid-cols-2"><form class="rounded-2xl border bg-white p-6" @submit.prevent="saveSettings"><h2 class="text-xl font-semibold">Meta e investimento</h2><p class="mt-3 text-sm leading-7 text-slate-500">A conversa de referência propõe começar com 30 empresas. Registre aqui o investimento real da sua prospecção, se houver.</p><label class="mt-5 block text-sm">Meta de empresas contatadas<input v-model.number="target" type="number" min="1" required class="mt-2 min-h-12 w-full rounded-lg border px-3"></label><label class="mt-5 block text-sm">Investimento total informado (R$)<input v-model.number="budget" type="number" min="0" step="0.01" required class="mt-2 min-h-12 w-full rounded-lg border px-3"></label><button :disabled="blocked || settingsSaving" class="mt-6 min-h-12 rounded-lg bg-[#2458df] px-5 py-3 text-sm text-white disabled:opacity-50">{{ settingsSaving ? 'Salvando…' : 'Salvar configuração' }}</button></form><section class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-semibold">Seus dados, com você</h2><p class="mt-3 text-sm leading-7 text-slate-500">O backup inclui empresas, observações, valores e histórico. Guarde o arquivo em um local seu. Os dados ficam no banco e podem ser acessados após entrar novamente.</p><div class="mt-6 flex flex-wrap gap-3"><button class="min-h-12 rounded-lg border px-5 py-3 text-sm" @click="store.exportBackup">Exportar backup</button><label class="inline-flex min-h-12 cursor-pointer items-center rounded-lg border px-5 py-3 text-sm">Importar backup<input type="file" accept=".json,application/json" class="sr-only" :disabled="blocked" @change="importFile"></label></div><div v-if="pendingImport" class="mt-6 rounded-xl bg-slate-50 p-5"><h3 class="text-sm font-semibold">Conferir importação</h3><p class="mt-3 text-sm leading-7">{{ pendingImport.leads.length }} empresas no arquivo. Registros com o mesmo identificador serão ignorados; seus contatos atuais serão preservados. Meta e investimento podem ser ajustados nas configurações.</p><div class="mt-4 flex flex-wrap gap-3"><button class="min-h-11 rounded-lg bg-[#2458df] px-4 text-sm text-white" @click="store.importBackup">Importar novos contatos</button><button class="min-h-11 px-3 text-sm" @click="pendingImport = null">Cancelar</button></div></div></section><section class="rounded-2xl border bg-white p-6 xl:col-span-2"><h2 class="text-xl font-semibold">Critérios da sua estratégia</h2><div class="mt-5 grid gap-6 md:grid-cols-3"><p class="text-sm leading-7"><strong>Quente</strong><br>Negócio ativo, com apresentação profissional, sem site próprio ou apenas Instagram.</p><p class="text-sm leading-7"><strong>Morno</strong><br>Negócio ativo, com um site antigo ou que precisa melhorar.</p><p class="text-sm leading-7"><strong>Revisar ou descartar</strong><br>Confira as informações faltantes. Sinais de abandono sugerem não priorizar; a decisão continua sendo sua.</p></div><p class="mt-5 text-xs leading-6 text-slate-500">Boas avaliações e fotos recentes reforçam a análise. A classificação pode ser ajustada manualmente, sem previsão de venda.</p></section></div>
          <section v-else class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="border-b p-5"><div v-if="view === 'Retornos'" class="mb-5 flex flex-wrap gap-2" role="group" aria-label="Fila de retornos"><button v-for="item in [{ key: 'overdue', label: 'Atrasados' }, { key: 'today', label: 'Para hoje' }, { key: 'unscheduled', label: 'Sem próximo passo' }, { key: 'upcoming', label: 'Próximos dias' }]" :key="item.key" class="min-h-11 rounded-lg border px-4 text-sm" :class="returnFilter === item.key ? 'bg-blue-600 text-white' : 'bg-white'" :aria-pressed="returnFilter === item.key" @click="returnFilter = item.key">{{ item.label }} · {{ returnCounts[item.key] }}</button></div><div class="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><h2 class="text-xl font-semibold">{{ view === 'Retornos' ? 'Quem precisa de um próximo passo?' : view === 'Arquivados' ? 'Contatos arquivados' : 'Sua lista de oportunidades' }}</h2><p class="mt-2 text-xs text-slate-500">{{ filtered.length }} empresas nesta seleção</p></div><div class="flex gap-2" role="group" aria-label="Visualização dos contatos"><button v-for="mode in ['Lista', 'Cartões', 'Funil']" :key="mode" :aria-pressed="arrangement === mode" class="min-h-11 rounded-lg border px-4 text-sm" :class="arrangement === mode ? 'bg-slate-100 font-semibold' : ''" @click="arrangement = mode">{{ mode }}</button></div></div><div class="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-[1.4fr_1fr_1fr_1fr_1fr]"><input v-model="query" aria-label="Buscar empresa ou pessoa" type="search" placeholder="Buscar empresa ou pessoa…" class="min-h-12 w-full rounded-lg border border-slate-200 px-3 text-base"><select v-model="city" aria-label="Filtrar cidade" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todas as cidades</option><option v-for="item in cities" :key="item">{{ item }}</option></select><select v-model="segment" aria-label="Filtrar segmento" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todos os segmentos</option><option v-for="item in segments" :key="item">{{ item }}</option></select><select v-model="priority" aria-label="Filtrar prioridade" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todas as prioridades</option><option>Quente</option><option>Morno</option><option>Revisar</option><option>Descartar</option></select><select v-model="stage" aria-label="Filtrar etapa" class="min-h-12 rounded-lg border border-slate-200 px-3 text-sm"><option value="">Todas as etapas</option><option v-for="item in prospectStages" :key="item" :value="item">{{ prospectStageLabels[item] }}</option></select></div><label class="mt-4 flex flex-wrap items-center gap-3 text-sm">Ordenar empresas<select v-model="sort" class="min-h-11 rounded-lg border px-3"><option value="newest">Cadastro: mais recentes</option><option value="oldest">Cadastro: mais antigas</option><option value="updated">Última atualização</option><option value="name">Nome: A–Z</option><option value="name-desc">Nome: Z–A</option><option value="rating">Avaliação: maior primeiro</option><option value="rating-asc">Avaliação: menor primeiro</option><option value="followup">Data do próximo retorno</option></select></label><button v-if="query || city || segment || priority || stage" class="mt-2 min-h-11 text-xs text-blue-700 underline" @click="store.clearFilters">Limpar filtros</button></div>
            <div v-if="!filtered.length && arrangement !== 'Funil'" class="px-6 py-16 text-center"><p class="text-3xl text-slate-300" aria-hidden="true">↗</p><h3 class="mt-4 text-xl font-semibold">{{ !data.leads.length ? 'Sua primeira empresa começa a lista.' : view === 'Retornos' ? 'Nenhum retorno pendente nesta seleção.' : 'Nenhuma empresa nesta seleção.' }}</h3><p class="mx-auto mt-3 max-w-md text-sm leading-7 text-slate-500">{{ !data.leads.length ? 'Escolha uma cidade, pesquise um segmento e registre o que encontrou antes de iniciar a conversa.' : 'Revise os filtros ou adicione uma nova oportunidade.' }}</p><button v-if="!data.leads.length" :disabled="blocked" class="mt-6 min-h-12 rounded-lg bg-blue-600 px-5 text-sm text-white" @click="editor?.open()">Cadastrar primeira empresa</button></div>
            <div v-else-if="arrangement === 'Lista'" class="overflow-x-auto" role="region" aria-label="Empresas cadastradas" tabindex="0"><table class="w-full min-w-[950px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th scope="col" class="p-4">Empresa</th><th scope="col" class="p-4">Etapa / prioridade</th><th scope="col" class="p-4">Avaliação</th><th scope="col" class="p-4">Cadastro</th><th scope="col" class="p-4">Próximo passo</th><th scope="col" class="p-4">Ações</th></tr></thead><tbody><tr v-for="lead in filtered" :key="lead.id" class="border-t hover:bg-slate-50"><td class="p-4"><button class="min-h-11 text-left font-semibold text-blue-700" @click="open(lead)">{{ lead.company }}</button><p class="text-xs text-slate-500">{{ lead.city }} · {{ lead.segment }}</p></td><td class="p-4">{{ prospectStageLabels[lead.stage] }}<p class="mt-1 text-xs text-slate-500">{{ heat(lead) }}</p></td><td class="p-4">{{ lead.rating ?? '—' }}<p class="text-xs text-slate-500">{{ lead.reviewCount ?? 0 }} avaliações</p></td><td class="whitespace-nowrap p-4">{{ new Date(lead.createdAt).toLocaleDateString('pt-BR') }}</td><td class="max-w-56 p-4"><p :class="lead.followUp && lead.followUp < today && !terminalStage(lead.stage) ? 'text-amber-700 font-semibold' : ''">{{ terminalStage(lead.stage) ? 'Encerrado' : lead.followUp ? lead.followUp.split('-').reverse().join('/') : 'Sem agendamento' }}</p><p class="mt-1 text-xs text-slate-500">{{ lead.nextAction }}</p></td><td class="p-4"><QuickActions :lead="lead" @log="open($event, true)" @schedule="schedule" /><button class="min-h-11 text-xs text-blue-700 underline" @click="open(lead)">Abrir ficha</button></td></tr></tbody></table></div>
            <TransitionGroup v-else-if="arrangement === 'Cartões'" name="lead-cards" tag="div" class="grid items-stretch gap-5 bg-[#f3f6fb] p-4 sm:grid-cols-2 sm:gap-6 sm:p-6 2xl:grid-cols-3"><LeadCard v-for="lead in filtered" :key="lead.id" :lead="lead" :today="today" @open="open" @log="open($event, true)" @schedule="schedule" /></TransitionGroup>
            <div v-else class="flex items-start gap-4 overflow-x-auto bg-slate-50 p-4" role="region" aria-label="Funil de empresas" tabindex="0"><section v-for="column in prospectStages" :key="column" class="w-80 shrink-0 rounded-2xl border border-slate-200 bg-slate-100 p-3"><h3 class="mb-4 flex justify-between gap-3 text-sm font-semibold">{{ prospectStageLabels[column] }} <span class="text-slate-500">{{ filtered.filter(lead => lead.stage === column).length }}</span></h3><p v-if="!filtered.some(lead => lead.stage === column)" class="py-8 text-center text-xs text-slate-500">Nenhuma empresa nesta etapa</p><TransitionGroup name="lead-cards" tag="div" class="grid gap-4"><LeadCard v-for="lead in filtered.filter(item => item.stage === column)" :key="lead.id" :lead="lead" :today="today" @open="open" @log="open($event, true)" @schedule="schedule" /></TransitionGroup></section></div>
          </section>
        </template>
      </div>
    </main>
    <dialog ref="scheduleDialog" aria-labelledby="schedule-title" class="m-auto w-[min(480px,94vw)] rounded-2xl p-6 backdrop:bg-slate-950/50"><form @submit.prevent="saveSchedule"><h2 id="schedule-title" class="text-xl font-semibold">Agendar retorno</h2><p class="mt-2 text-sm">{{ scheduleLead?.company }}</p><label class="mt-5 block text-sm">Data<input v-model="scheduleDate" type="date" :min="today" required class="mt-2 min-h-12 w-full rounded-lg border px-3"></label><label class="mt-4 block text-sm">Próxima ação<input v-model="scheduleAction" required maxlength="500" class="mt-2 min-h-12 w-full rounded-lg border px-3"></label><p class="mt-3 text-xs text-slate-500">Agendar não registra um contato realizado.</p><p v-if="scheduleError" role="alert" class="mt-3 text-sm text-rose-700">{{ scheduleError }}</p><div class="mt-5 flex gap-3"><button :disabled="scheduleSaving" class="min-h-11 rounded-lg bg-blue-600 px-4 text-white disabled:opacity-50">{{ scheduleSaving ? 'Salvando…' : 'Salvar retorno' }}</button><button type="button" :disabled="scheduleSaving" class="min-h-11 px-4" @click="scheduleDialog?.close()">Cancelar</button></div></form></dialog>
    <LeadEditor ref="editor" :save="store.save" /><LeadDetail ref="detail" :lead="selected" :log="store.log" @edit="editor?.open($event)" @archive="store.archive" @reopen="store.reopen" />
  </div>
</template>

<style scoped>
.lead-cards-enter-active, .lead-cards-leave-active, .lead-cards-move { transition: opacity .22s ease, transform .22s ease; }
.lead-cards-enter-from, .lead-cards-leave-to { opacity: 0; transform: translateY(10px); }
@media (prefers-reduced-motion: reduce) {
  .lead-cards-enter-active, .lead-cards-leave-active, .lead-cards-move { transition: none; }
  .lead-cards-enter-from, .lead-cards-leave-to { transform: none; }
}
</style>
